/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { EditConflictService } from '../edit-conflict/edit-conflict.service';
import { BaseEditAction } from './base-edit-action';

interface Item {
  uid: string;
  name: string;
}

const acl = signal<{ generic: Acl } | undefined>(undefined);
const repository = {
  acl: () => Object.assign(acl, { fetch: jasmine.createSpy('fetch') }) as any,
  update: jasmine.createSpy('update'),
};

@Component({ selector: 'test-edit-action', template: '' })
class TestEditAction extends BaseEditAction<Item> {
  protected readonly scope = 'test';
  protected readonly repository = repository;
  protected readonly toValue = (item: Item) => ({ ...item });
}

describe('BaseEditAction', () => {
  let conflicts: jasmine.SpyObj<EditConflictService>;
  let action: TestEditAction;
  let container: jasmine.SpyObj<any>;

  beforeEach(() => {
    conflicts = jasmine.createSpyObj<EditConflictService>('EditConflictService', ['save']);
    TestBed.configureTestingModule({
      imports: [TestEditAction, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
      providers: [{ provide: EditConflictService, useValue: conflicts }],
    });
    const fixture = TestBed.createComponent(TestEditAction);
    fixture.detectChanges();
    action = fixture.componentInstance;
    container = jasmine.createSpyObj('ActionContainerComponent', ['close']);
    action.container.set(container);
    action.selection = signal([{ uid: 'a', name: 'old' }]);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('is visible with the create permission', () => {
    acl.set({ generic: { allows: [{ name: 'create', allowed: true }] } });
    expect(action.visible([])()).toBeTrue();
  });

  it('loads the selection and saves through the conflict resolver', () => {
    conflicts.save.and.returnValue(of({ uid: 'a', name: 'new' }));
    action.run();
    action.form.setValue({ uid: 'a', name: 'new' });

    action.save([]);

    const request = conflicts.save.calls.mostRecent().args[0];
    expect(request.value).toEqual({ uid: 'a', name: 'new' });
    expect(request.original).toEqual({ uid: 'a', name: 'old' });
    expect(action.saving()).toBeFalse();
    expect(container.close).toHaveBeenCalled();
  });

  it('applies the merged value and keeps the form dirty', () => {
    conflicts.save.and.returnValue(of());
    action.run();
    action.save([]);

    conflicts.save.calls.mostRecent().args[0].merged!({ uid: 'a', name: 'merged' }, { uid: 'a', name: 'theirs' });

    expect(action.form.value).toEqual({ uid: 'a', name: 'merged' });
    expect(action.form.dirty).toBeTrue();
  });
});
